/**
 * L2: one Chinese line per card, generated by the session's model (S18).
 *
 * Strictly best-effort. Every failure path — no llm service, a model error, a
 * malformed answer — returns an empty result so the L1 line rendered earlier
 * simply stays in place. This module never throws.
 */
import { SYSTEM_PROMPT, buildUserPrompt, type PromptRepo } from './prompts.js'
import { looksChinese, truncate } from './zh.js'

export interface SummaryRow {
  fullName: string
  zh: string
  why?: string
}

/** Minimal structural face of `ctx.llm`; avoids a hard dependency on the package. */
export interface LlmLike {
  stream: (options: Record<string, unknown>) => AsyncIterable<unknown>
}

export interface SummarizeDeps {
  llm: LlmLike
  provider?: string
  model?: string
  batchSize?: number
  timeoutMs?: number
  signal?: AbortSignal
  /** Cached L1.5 result for a repository, keyed by fullName+description. */
  cachedZh?: (repo: PromptRepo) => string | undefined
  /** Called as soon as one batch validates, so cards upgrade incrementally. */
  onBatch?: (rows: SummaryRow[]) => void
  log?: (message: string) => void
}

const MAX_ZH_LENGTH = 60
const MAX_WHY_LENGTH = 24
const URL_PATTERN = /(?:https?:\/\/|www\.)/i
const DEFAULT_BATCH = 5
const DEFAULT_TIMEOUT_MS = 20_000

let fallbackIdSeq = 0

/**
 * One user-role message, built structurally.
 *
 * `createUserMessage()` from `@deepseek-ai/dsh-llm` is literally
 * `{...input, role: 'user', id: randomUUID()}` frozen — importing the package
 * would add nothing but a host-version coupling, so the shape is built here.
 */
function buildUserMessage(text: string): Record<string, unknown> {
  const cryptoFace = globalThis.crypto as { randomUUID?: () => string } | undefined
  const id =
    typeof cryptoFace?.randomUUID === 'function'
      ? cryptoFace.randomUUID()
      : `radar-${Date.now().toString(36)}-${(fallbackIdSeq += 1)}`
  return {
    id,
    role: 'user',
    content: [{ type: 'text', text }],
    source: { kind: 'user' },
  }
}

/** Strip code fences and isolate the outermost JSON array. */
export function extractJsonArray(text: string): unknown[] | undefined {
  const withoutFences = text.replace(/```(?:json)?/gi, ' ').replace(/```/g, ' ')
  const start = withoutFences.indexOf('[')
  if (start < 0) return undefined
  const body = withoutFences.slice(start)
  const end = body.lastIndexOf(']')
  if (end > 0) {
    try {
      const parsed: unknown = JSON.parse(body.slice(0, end + 1))
      if (Array.isArray(parsed)) return parsed
    } catch {
      /* the answer may have been cut off: fall through and salvage */
    }
  }
  // A token-limit cut leaves the array unterminated. Keep the rows that did
  // arrive instead of dropping the whole batch on the floor.
  const lastBrace = body.lastIndexOf('}')
  if (lastBrace > 0) {
    try {
      const parsed: unknown = JSON.parse(`${body.slice(0, lastBrace + 1)}]`)
      if (Array.isArray(parsed)) return parsed
    } catch {
      /* fall through to the per-object scan */
    }
  }
  // Last resort: a raw newline inside a string, an unescaped quote or any
  // other formatting slip invalidates the whole document. Parse the objects
  // one by one so one bad row cannot cost the batch.
  const objects = scanObjects(body)
  if (objects.length === 0) return undefined
  const rows: unknown[] = []
  for (const object of objects) {
    try {
      rows.push(JSON.parse(object.replace(/[\u0000-\u001f]+/gu, ' ')))
    } catch {
      /* skip this row only */
    }
  }
  return rows.length === 0 ? undefined : rows
}

/** Collect balanced `{...}` spans, ignoring braces inside strings. */
function scanObjects(source: string): string[] {
  const objects: string[] = []
  let depth = 0
  let start = -1
  let inString = false
  let escaped = false
  for (let index = 0; index < source.length; index += 1) {
    const char = source[index]
    if (inString) {
      if (escaped) escaped = false
      else if (char === '\\') escaped = true
      else if (char === '"') inString = false
      continue
    }
    if (char === '"') {
      inString = true
      continue
    }
    if (char === '{') {
      if (depth === 0) start = index
      depth += 1
      continue
    }
    if (char === '}') {
      depth -= 1
      if (depth === 0 && start >= 0) {
        objects.push(source.slice(start, index + 1))
        start = -1
      }
      if (depth < 0) depth = 0
    }
  }
  return objects
}

/** Validate a model answer against the batch it was asked about. */
export function parseSummaryResponse(
  text: string,
  expected: readonly PromptRepo[],
): SummaryRow[] {
  const parsed = extractJsonArray(text)
  if (parsed === undefined) return []
  const wanted = new Set(expected.map((repo) => repo.fullName))
  const rows: SummaryRow[] = []
  const seen = new Set<string>()
  for (const item of parsed) {
    if (item === null || typeof item !== 'object') continue
    const record = item as Record<string, unknown>
    const fullName = typeof record.fullName === 'string' ? record.fullName.trim() : ''
    const rawZh = typeof record.zh === 'string' ? record.zh.trim() : ''
    if (fullName === '' || rawZh === '' || !wanted.has(fullName)) continue
    if (seen.has(fullName)) continue
    if (URL_PATTERN.test(rawZh)) continue
    if (!looksChinese(rawZh, 0.3)) continue
    const zh = truncate(rawZh, MAX_ZH_LENGTH)
    if (zh === '') continue
    seen.add(fullName)
    const rawWhy = typeof record.why === 'string' ? record.why.trim() : ''
    const why =
      rawWhy !== '' && !URL_PATTERN.test(rawWhy) && looksChinese(rawWhy, 0.3)
        ? truncate(rawWhy, MAX_WHY_LENGTH)
        : undefined
    rows.push({ fullName, zh, ...(why === undefined ? {} : { why }) })
  }
  return rows
}

function chunkText(chunk: unknown): string {
  if (typeof chunk === 'string') return chunk
  if (chunk === null || typeof chunk !== 'object') return ''
  const record = chunk as Record<string, unknown>
  for (const key of ['text', 'delta', 'content']) {
    const value = record[key]
    if (typeof value === 'string') return value
  }
  const block = record.block
  if (block !== null && typeof block === 'object') {
    const text = (block as Record<string, unknown>).text
    if (typeof text === 'string') return text
  }
  return ''
}

async function runOneBatch(
  batch: readonly PromptRepo[],
  deps: SummarizeDeps,
): Promise<SummaryRow[]> {
  const user = buildUserPrompt(batch)
  const messages = [buildUserMessage(user)]

  const options: Record<string, unknown> = {
    messages,
    system: SYSTEM_PROMPT,
    maxTokens: 1200,
    signal: deps.signal ?? AbortSignal.timeout(deps.timeoutMs ?? DEFAULT_TIMEOUT_MS),
  }
  if (deps.provider !== undefined && deps.provider !== '') options.provider = deps.provider
  if (deps.model !== undefined && deps.model !== '') options.model = deps.model

  const started = Date.now()
  let text = ''
  let finish: unknown
  for await (const chunk of deps.llm.stream(options)) {
    text += chunkText(chunk)
    const record = chunk as { type?: unknown; finishReason?: unknown } | null
    if (record !== null && typeof record === 'object' && record.type === 'finish') finish = record.finishReason
  }
  const rows = parseSummaryResponse(text, batch)
  deps.log?.(`AI 结束：${text.length} 字 / ${Date.now() - started}ms / rows=${rows.length}${finish === undefined ? '' : ` / finish=${String(finish)}`}`)
  if (rows.length === 0) {
    // One line of evidence for the diagnostics trail: an empty answer, a
    // refusal and a validation drop all look identical from the outside.
    const parsed = extractJsonArray(text)
    deps.log?.(`AI 原文（${text.length} 字）：${text.replace(/\s+/g, ' ').slice(0, 240)}`)
    deps.log?.(`AI 结尾（${text.length} 字）：${text.replace(/\s+/g, ' ').slice(-160)}`)
    deps.log?.(
      `AI 校验：parsed=${parsed === undefined ? 'none' : parsed.length} expected=${batch.map((repo) => repo.fullName).join(' | ')}`,
    )
  }
  return rows
}

/**
 * Ask the model for Chinese one-liners. Returns `fullName -> zh`.
 * Never throws; a rejected batch is simply missing from the result.
 */
export async function summarizeCards(
  repos: readonly PromptRepo[],
  deps: SummarizeDeps,
): Promise<Record<string, string>> {
  const out: Record<string, string> = {}
  const pending: PromptRepo[] = []

  for (const repo of repos) {
    const cached = deps.cachedZh?.(repo)
    if (cached !== undefined && cached !== '') {
      out[repo.fullName] = cached
      continue
    }
    pending.push(repo)
  }
  if (pending.length === 0) return out

  const batchSize = Math.max(1, Math.min(deps.batchSize ?? DEFAULT_BATCH, 5))

  for (let i = 0; i < pending.length; i += batchSize) {
    const batch = pending.slice(i, i + batchSize)
    try {
      const rows = await runOneBatch(batch, deps)
      if (rows.length === 0) {
        deps.log?.(`AI 摘要批次无有效结果（${batch.length} 条）`)
        continue
      }
      for (const row of rows) out[row.fullName] = row.zh
      deps.onBatch?.(rows)
    } catch (error) {
      deps.log?.(`AI 摘要失败：${error instanceof Error ? error.message : String(error)}`)
    }
  }
  return out
}

export { MAX_ZH_LENGTH }
